<span class="line"><span style="color:#E1E4E8;">    --set-gtid-purged</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">OFF</span><span style="color:#79B8FF;"> \\ </span><span style="color:#6A737D;">   # 适用于GTID环境</span></span>
