<span class="line"><span style="color:#B392F0;">mysqldump</span><span style="color:#79B8FF;"> -u</span><span style="color:#9ECBFF;"> root</span><span style="color:#79B8FF;"> -p</span><span style="color:#79B8FF;"> --no-create-info</span><span style="color:#9ECBFF;"> ecommerce</span><span style="color:#F97583;"> &gt;</span><span style="color:#9ECBFF;"> data_only.sql</span></span>
